const request = $('Webhook').first().json.body || {};
const page = $input.first().json.pages?.[0];
const query = String(request.query || '').trim();
if (query.length < 2 || query.length > 120) {
  throw new Error('query must be between 2 and 120 characters');
}
const terms = [...new Set(query.toLowerCase().match(/[a-z0-9]{3,}/g) || [])];
const text = [page?.title, page?.description, page?.excerpt].filter(Boolean).join(' ').toLowerCase();
const matchedTerms = terms.filter(term => text.includes(term));
const confidence = terms.length ? Math.round(matchedTerms.length / terms.length * 100) : 0;
const found = Boolean(page);
return [{ json: {
  requestId: String(Date.now()),
  query,
          status: !found ? 'no_reference_found' : confidence >= 70 ? 'reference_found' : 'needs_review',
  confidence,
  matchedTerms,
  totalTerms: terms.length,
  reference: page ? {
    title: page.title,
    description: page.description || '',
    excerpt: String(page.excerpt || '').replace(/<[^>]*>/g, ''),
    url: 'https://en.wikipedia.org/wiki/' + encodeURIComponent(page.title.replaceAll(' ', '_'))
  } : null,
  message: 'A Wikipedia match is a lead for human review, not proof or official verification.',
  pipeline: [
    { name: 'Receive place or claim', status: 'complete' },
    { name: 'Query Wikimedia reference index', status: 'complete' },
    { name: 'Compare matching terms', status: 'complete' },
    { name: 'Return cited result for human review', status: 'complete' }
  ]
} }];
